#!/usr/bin/env bash
# Native Android PDF check using disposable fixtures generated by test-pdf-engine.sh.
# Select the intended emulator/tablet with ANDROID_SERIAL when more than one is connected.
set -euo pipefail
ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
APP="app/build/outputs/apk/release/app-release.apk"
CLASSES="app/build/intermediates/javac/release/compileReleaseJavaWithJavac/classes"
OUTPUT="build/pdf-open-check"
[[ -f "$APP" && -f build/pdf-engine-test/scan-384-mib.pdf ]] || {
  echo 'Run scripts/test-pdf-engine.sh and scripts/build-release.sh first.' >&2; exit 1;
}
export JAVA_HOME="$ROOT/.tools/jdk-17.0.21+9"
export PATH="$JAVA_HOME/bin:$PATH"
mkdir -p "$OUTPUT/classes" "$OUTPUT/dex"
javac -encoding UTF-8 -source 8 -target 8 \
  -classpath ".tools/platform-29/android.jar:$CLASSES:.tools/pdfbox/*" \
  -d "$OUTPUT/classes" tools/NotebookPdfOpenCheck.java
.tools/build-tools-36.0.0/d8 --min-api 29 --lib .tools/platform-29/android.jar \
  --classpath "$APP" --output "$OUTPUT/dex" \
  "$OUTPUT/classes/org/eink/inkprobe/notebook/NotebookPdfOpenCheck.class"
python3 - <<'PY'
from zipfile import ZipFile
with ZipFile('build/pdf-open-check/check.jar', 'w') as archive:
    archive.write('build/pdf-open-check/dex/classes.dex', 'classes.dex')
PY
REMOTE="/data/local/tmp/scriflow-pdf-open-$$"
trap 'adb shell rm -rf "$REMOTE" >/dev/null 2>&1 || true' EXIT
adb shell mkdir -p "$REMOTE"
adb push "$OUTPUT/check.jar" "$APP" build/pdf-engine-test/source.pdf \
  build/pdf-engine-test/encrypted.pdf build/pdf-engine-test/encrypted-aes-128.pdf \
  build/pdf-engine-test/encrypted-aes-256.pdf build/pdf-engine-test/scan-384-mib.pdf "$REMOTE/" >/dev/null
adb shell "CLASSPATH=$REMOTE/check.jar:$REMOTE/app-release.apk app_process /system/bin org.eink.inkprobe.notebook.NotebookPdfOpenCheck $REMOTE"
adb pull "$REMOTE/native-pdf-result.json" "$OUTPUT/result.json" >/dev/null
